import { Title } from "@solidjs/meta";
import { action, useAction, useSubmission } from "@solidjs/router";
import { createSignal, Show } from "solid-js";
import {
  hasErrors,
  readContactForm,
  validateContact,
  type ContactErrors,
  type ContactResult,
} from "~/lib/contact";

const sendMessage = action(async (formData: FormData): Promise<ContactResult> => {
  "use server";
  const values = readContactForm(formData);
  const errors = validateContact(values);
  if (hasErrors(errors)) return { ok: false, errors, values };
  return { ok: true, name: values.name.trim() };
}, "sendMessage");

export default function Contact() {
  const submission = useSubmission(sendMessage);
  const send = useAction(sendMessage);
  const [clientErrors, setClientErrors] = createSignal<ContactErrors | null>(null);

  const result = () => submission.result;
  const errors = (): ContactErrors => {
    const fromClient = clientErrors();
    if (fromClient) return fromClient;
    const res = result();
    return res && !res.ok ? res.errors : {};
  };
  const sentValue = (field: "name" | "email" | "message") => {
    const res = result();
    return res && !res.ok ? res.values[field] : "";
  };
  const success = () => {
    const res = result();
    return !clientErrors() && res && res.ok ? res.name : undefined;
  };

  const onSubmit = (event: SubmitEvent) => {
    event.preventDefault();
    const form = event.currentTarget as HTMLFormElement;
    const formData = new FormData(form);
    const found = validateContact(readContactForm(formData));
    if (hasErrors(found)) {
      setClientErrors(found);
      return;
    }
    setClientErrors(null);
    void send(formData).then(res => {
      if (res.ok) form.reset();
    });
  };

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={success()}>
        {name => (
          <p role="status" class="success">
            Thanks, {name()}! Your message has been sent.
          </p>
        )}
      </Show>
      <form action={sendMessage} method="post" novalidate onSubmit={onSubmit}>
        <div class="field">
          <label for="contact-name">Name</label>
          <input
            id="contact-name"
            name="name"
            type="text"
            value={sentValue("name")}
            aria-invalid={errors().name ? "true" : undefined}
            aria-describedby={errors().name ? "contact-name-error" : undefined}
          />
          <Show when={errors().name}>
            {message => (
              <p id="contact-name-error" class="error">
                {message()}
              </p>
            )}
          </Show>
        </div>
        <div class="field">
          <label for="contact-email">Email</label>
          <input
            id="contact-email"
            name="email"
            type="email"
            value={sentValue("email")}
            aria-invalid={errors().email ? "true" : undefined}
            aria-describedby={errors().email ? "contact-email-error" : undefined}
          />
          <Show when={errors().email}>
            {message => (
              <p id="contact-email-error" class="error">
                {message()}
              </p>
            )}
          </Show>
        </div>
        <div class="field">
          <label for="contact-message">Message</label>
          <textarea
            id="contact-message"
            name="message"
            rows={6}
            value={sentValue("message")}
            aria-invalid={errors().message ? "true" : undefined}
            aria-describedby={errors().message ? "contact-message-error" : undefined}
          />
          <Show when={errors().message}>
            {message => (
              <p id="contact-message-error" class="error">
                {message()}
              </p>
            )}
          </Show>
        </div>
        <button type="submit" disabled={submission.pending}>
          Send
        </button>
      </form>
    </>
  );
}
