import { createMiddleware } from "@solidjs/start/middleware";

// SolidStart answers a no-JS form post with a redirect and carries the action's
// result in a `Secure` flash cookie. Over plain http some clients drop `Secure`
// cookies, so the flag is removed there and the result still reaches the page.
export default createMiddleware([
  async (event, next) => {
    const response = await next();
    if (!(response instanceof Response) || new URL(event.req.url).protocol !== "http:") {
      return response;
    }
    const cookies = response.headers.getSetCookie();
    if (!cookies.some(cookie => cookie.startsWith("flash="))) return response;
    const headers = new Headers(response.headers);
    headers.delete("Set-Cookie");
    for (const cookie of cookies) {
      headers.append(
        "Set-Cookie",
        cookie.startsWith("flash=")
          ? cookie.replace(/;\s*Secure/i, "").replace(/;?\s*$/, "; Path=/; SameSite=Lax")
          : cookie,
      );
    }
    return new Response(response.body, {
      status: response.status,
      statusText: response.statusText,
      headers,
    });
  },
]);
