import { createAsync, useLocation } from "@solidjs/router";
import type { ParentProps } from "solid-js";
import { getBooks } from "~/lib/books";

const sections = [
  { href: "/books", label: "Books" },
  { href: "/about", label: "About" },
  { href: "/contact", label: "Contact" },
];

export default function Layout(props: ParentProps) {
  const location = useLocation();
  const books = createAsync(() => getBooks(), { deferStream: true });

  // "Books" stays current on the book pages, but not on the 404 of an unknown slug.
  const isCurrent = (href: string) => {
    const path = location.pathname.replace(/\/+$/, "") || "/";
    if (path === href) return true;
    if (href !== "/books" || !path.startsWith("/books/")) return false;
    const slug = decodeURIComponent(path.slice("/books/".length));
    return books()?.some(book => book.slug === slug) ?? false;
  };

  return (
    <>
      <header class="site-header">
        <a href="/" class="brand">
          Bookshelf
        </a>
        <nav aria-label="Main">
          {sections.map(section => (
            <a href={section.href} aria-current={isCurrent(section.href) ? "page" : undefined}>
              {section.label}
            </a>
          ))}
        </nav>
      </header>
      <main>{props.children}</main>
      <footer class="site-footer">
        <p>© Bookshelf</p>
      </footer>
    </>
  );
}
